-- READ-ONLY verification for m2_flexible_questions_PROPOSED.sql. Changes nothing (it only CALLS the pure validator
-- on synthetic content and reads stored versions). Every row must say PASS.
with sample as (select to_jsonb(array[repeat('word ', 25)]) as passage),
fn as (select prosrc, proacl::text acl, provolatile from pg_proc where oid = 'public.m2_assessment_content_issues(text,jsonb,jsonb)'::regprocedure),
checks(name, ok) as (values
  ('validator is the reviewed 5-8 body', (select md5(prosrc) = 'c349c8b5fbea59de2b3ca99658e0878a' from fn)),
  ('5, 6, 7 and 8 questions are accepted', cardinality(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 5) g))) = 0 and cardinality(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 6) g))) = 0 and cardinality(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 7) g))) = 0 and cardinality(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 8) g))) = 0),
  ('4 and 9 questions are refused', 'Add 5 to 8 comprehension questions.' = any(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 4) g))) and 'Add 5 to 8 comprehension questions.' = any(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal','inferential','critical'])[1 + (g - 1) % 3],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 9) g)))),
  ('one literal, one inferential and one critical question are still required',
    'Include at least one literal, one inferential and one critical question.' = any(public.m2_assessment_content_issues('T', (select passage from sample), (select jsonb_agg(jsonb_build_object('id','q'||g,'type',(array['literal'])[1 + (g - 1) % 1],'prompt','P','correctChoiceId','a','choices',jsonb_build_array(jsonb_build_object('id','a','label','a'),jsonb_build_object('id','b','label','b'),jsonb_build_object('id','c','label','c'),jsonb_build_object('id','d','label','d')))) from generate_series(1, 5) g)))),
  ('every stored submitted, approved, published or retired version still passes the structural check',
    not exists (select 1 from public.m2_assessment_package_versions v where v.status <> 'draft'
                and cardinality(public.m2_assessment_content_issues(v.passage_title, v.paragraphs, v.questions)) > 0)),
  ('still immutable and callable by the backend (service_role) only',
    (select provolatile = 'i' and acl like '%service_role=X/%' and acl not like '%authenticated%' and acl not like '%anon%' from fn))
)
select case when ok then 'PASS' else 'FAIL' end as result, name from checks;
